/* 易 EKI Pro — Service Worker
   アプリ本体をキャッシュし、オフラインでも開けるようにする。
   ※ AIによる鑑定文生成（Gemini）はオンライン時のみ。立卦・顧客管理・印刷はオフライン可。 */
const CACHE = 'eki-pro-v40'; /* v40=鑑定書の共有ボタンと答えの行が途中で折り返さないように。v39= v39=鑑定書（お客様向け）に専門用語（卦・変爻）を出さない。v38= v38=〇△と卦全体の向きが違うときの説明・決まり文句を卦に合わせる・相手のいない相談で「相手の立場」と言わない・要点の句点・会社情報の住所統一。v37= v37=命にかかわる相談に窓口を表示・病気/離婚/投資などは〇△で断定しない・卦の解説の誤字ときつい表現を修正・障害時の返金（48時間）。v36= v36=上部タブが固定されない不具合を修正／ロック画面から顧客名簿を書き出し／引き継ぎメモをページから削除／規約・特商法に回数上限・解約期限を明記ほか。 v32=紹介ページの「開発者の声（水木 にこ）」を削除（docs/ に保存）。 / v31=ご相談の入力欄・深掘り相談の下にあった「🔒 ご相談の文章は…外部の文章作成サービス（Google）へ送られます…」の説明文を削除（プライバシーポリシーには記載のまま）。 / v30=LP：「易タロット」が語の途中で改行しないように。 / v29=顧客名簿：端末の保存容量がいっぱいのときは「保存できませんでした」と必ず知らせ、8割を超えたら書き出し（バックアップ）を案内。 / v28=音声入力（録音して議事録にする）機能を取り外し（ボタン・仕組み・文言・マイクの利用をすべて削除）。 / v27=お客様にお渡しする鑑定書（オンライン作成）に、易の専門用語・漢文・四柱推命の専門用語が残ったら1回作り直し、それでも残れば専門用語なしの定型文にする。 / v26=詳細鑑定の文章に「AI」という言葉が出ないように（作成時の指示に加え、「私はAIなので」「AIの分析では」等の言い回しを画面・印刷・コピー・共有の前に取り除く。相談内容としてのAIの話題はそのまま）。 / v25=ログイン画面がスマホで横にはみ出す不具合を修正（本体とフッターが横並びになっていた）。「この端末でログインしたままにする」が語の途中で改行しないように。 / v24=本番ドメイン ekipro.jp をOGP・特商法の販売URLに記入。 / v23=「八卦」の読みを「はっけ」に統一（用語タブ）。 / v22=規約・特商法・プライバシーポリシーをPRO・ビギナーと同じ内容に作り直し（自分のお客様への鑑定・鑑定書はOK、解約しても期間の最終日まで、障害時はメール解約、二重申込、無料期間の数え方、無料期間中のオンライン鑑定は1日3回、相談者情報・国外提供・安全管理措置）。最終確認画面に日付入りの無料期間・初回課金日・解約期限。LPに税込表示。 v21=ログインを作り直し（PRO・ビギナーと共通）：パスワードを端末に保存せずトークンでログインしたまま／解約しても期間の最終日まで使える／電波が弱くても待たずに開く／ログアウトと規約・特商法へのリンクを設定画面に／オンライン鑑定に会員確認。八卦の読みを教科書と同じ「はっか」に。実装仕様書を整理（旧検討の決済代行の記述を削除、会員まわりの共通仕様を同梱）。 v20=総点検の修正：有料会員には回数制限・最終日の案内を出さない／無料お試しの上限後も内蔵データで鑑定を続ける／動いた爻の吉凶（凶・厲・吝・勿用など）を答えに反映し画面内の矛盾をなくす／新しい鑑定で前のお客様の情報を消す／相談テーマ未選択時は相談文から推定／鑑定書の印刷で白紙に近い2枚目を出さない／64卦一覧を新しい現代語訳に統一／爻の現代語訳の誤りを修正／コイン式の説明を実際の決め方に合わせる／お客様のお名前を外部に送らない／名簿の読み込みに確認／電波が弱いときは3秒で保存版から起動／用語集に上卦・下卦・无咎・吝などを追加／LP：架空の利用者の声を削除・機能表示を実物に合わせる・錯卦＝さくか・無料期間の条件を明記。 v19=本によって読みが分かれる所を一般によく知られた読みに統一（革の已日（いじつ）、漸の上爻は陸（りく）、既済は亨（とお）ること小（しょう）なり、屯の三爻は君子（くんし）幾（き）なれば舎（す）つるに如（し）かず ほか）。「貞（てい）にすべからず」の4か所は鑑定者確認済み。 v18=64卦の卦辞・384の爻辞すべてに読み下し（読み仮名つき）を追加し、結果画面・台本・参考一覧に表示。省略されていた原文を全文に、誤字（簡体字の厉・巩、干野→于野、蹇蹣→蹇蹇、莫陵→莧陸 など）を正しい字に。オンライン鑑定は読み下しを一字一句そのまま使うよう指示。読みの方針：元亨利貞＝元（おお）いに亨（とお）る・貞（ただ）しきに利（よろ）し、元吉＝元（おお）いに吉（きち）、貞凶＝貞（ただ）しけれども凶、吝（りん）、悔（く）い亡（ほろ）ぶ、井（せい）、女（おんな）。 v17=易の言葉に読み仮名を（）で付ける：易経（えききょう）・卦辞（かじ）・爻辞（こうじ）・本卦（ほんか）・之卦（しか）・互卦（ごか）・綜卦（そうか）・錯卦（さくか）・変爻（へんこう）・立卦（りっか）・上卦（じょうか）・下卦（かか）・内卦（ないか）・外卦（がいか）・初爻（しょこう）〜上爻（じょうこう）・四爻（しこう）・八卦の読み。天雷无妄（てんらいむぼう）・火雷噬嗑（からいぜいこう）に統一。オンライン鑑定にも同じ読みを指示。鑑定書は読み仮名ごと専門用語を出さない。 v16=オンライン鑑定の指示を改善：お客様の名前で呼ぶ（伏せ字・方言なし）、動いた爻と之卦を取り違えない、運気と爻の吉凶が食い違うときは爻を重く見て矛盾なく説明、原文は句読点まで正確に。圏外の定型文でも爻が凶のときは注意を添える。 v15=録音（声の議事録）ボタンを撤去、メモ欄を広く。顧客の履歴に相談テーマを日本語で表示。iPhoneで入力時に画面が拡大されないよう入力文字16px。圏外でも30日以内にログイン確認済みの会員は使える。 v14=アプリ画面・台本・要点・深掘り相談は易経の原文（卦の名前・卦辞・爻辞）を正確に示し、必ず「現代語にすると」を添える形に（教科書として原文を残す）。専門用語なしはお客様にお渡しする鑑定書だけ。 v13=お客様に話す言葉（台本・要点・判定・深掘り相談・鑑定書）を専門用語なしの現代語に（64卦の意味・爻の言葉を現代語に、卦の名前・漢文は出さない／オンライン鑑定にも厳守させ取りこぼしは置きかえ）。結果画面は「今回の結果」を現代語で表示し、卦の名前・図・原文は「鑑定士用の参考」に折りたたみ。「専門的に」の切り替えは廃止。 v12=鑑定書を充実：ご相談への答え・いまの状況・これからの流れ・生まれ持った性質と時期の目安（四柱推命・生年月日があるとき）・具体的なアドバイス・結びのことば。オンライン鑑定で生成／オフラインは定型文。 v11=鑑定書：鑑定士用の「要点」を載せない、同じ文のくり返しを除く、印刷で同じページが何枚も出る不具合を修正（鑑定書だけを1枚に）、背景を白に、行末の泣き別れ防止。 v10=アプリにログイン画面（会員ゲート：メール＋パスワード）を追加。決済接続までは PREVIEW_MODE=true で誰でも開ける。 v9=メールアドレスを忘れた・間違えた・変えたいを、お客様が自分で解決できるように。v8=二重申込はお客様の自己責任（返金なし）の案内に。v7=決済をテレコムクレジットに統一：申込（メール2回入力・最終確認・完了／失敗画面）・ログイン・マイページを新設。v6=料金を月額9,800円のみに統一（半年・年間プラン廃止）。v5=点検修正：命式をPRO版と同じ計算エンジンに・オンライン鑑定をサーバー中継に・本番でキー入力欄と引き継ぎメモを非表示・オンライン鑑定の印・AI表記の言い換え */
const ASSETS = [
  './',
  './index.html',
  './manifest.json',
  './icon-192.png',
  './icon-512.png',
  './apple-touch-icon-180.png'
];

self.addEventListener('install', e => {
  self.skipWaiting();
  // 1件失敗しても他は残るよう個別に取得（本体index.htmlの取りこぼし防止）
  e.waitUntil(caches.open(CACHE).then(c => Promise.all(ASSETS.map(a => c.add(a).catch(() => {})))));
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const sameOrigin = url.origin === location.origin;
  const isFont = /fonts\.(googleapis|gstatic)\.com/.test(url.host);

  // Gemini等の外部API・他オリジンは触らない（常にネットワーク）
  if (!sameOrigin && !isFont) return;

  // ページ遷移：ネット優先。ただし電波が弱く3秒待っても返ってこないときは、保存してある本体ですぐ起動する
  // （裏で取得できたら次回のために保存しておく）
  if (req.mode === 'navigate') {
    const fromCache = () => caches.match(req, { ignoreSearch: true })
      .then(m => m || caches.match('./index.html'))
      .then(m => m || caches.match('./'));
    const net = fetch(req).then(r => {
      if (r && r.ok) { const cp = r.clone(); caches.open(CACHE).then(c => c.put(req, cp)); }
      return r;
    });
    e.respondWith(new Promise(resolve => {
      let done = false;
      const timer = setTimeout(() => { fromCache().then(m => { if (m && !done) { done = true; resolve(m); } }); }, 3000);
      net.then(r => { if (!done) { done = true; clearTimeout(timer); resolve(r); } })
         .catch(() => { clearTimeout(timer); fromCache().then(m => { if (!done) { done = true; resolve(m || Response.error()); } }); });
    }));
    return;
  }

  // それ以外（CSS/JS/画像/フォント）：キャッシュ優先 → ネット（取得できたら保存）
  e.respondWith(
    caches.match(req).then(m => m || fetch(req).then(r => {
      if (r && r.status === 200 && (sameOrigin || /fonts\.gstatic/.test(url.host))) {
        const cp = r.clone();
        caches.open(CACHE).then(c => c.put(req, cp));
      }
      return r;
    }).catch(() => m))
  );
});
